-- zlib (compression) -- mirrors extern/zlib built from source.
-- zconf.h is generated by zlib's own CMake; we use the pre-generated copy under
-- premake/config/<platform>/zlib/.
project "zlib"
    kind "StaticLib"
    language "C"
    set_output("static")

    files { DEPS_EXTERN .. "/zlib/*.c" }
    includedirs { DEPS_EXTERN .. "/zlib" }

    filter "system:linux"
        includedirs { CONFIG_DIR .. "/linux/zlib" }
        defines { "_LARGEFILE64_SOURCE=1" }
    filter "system:windows"
        includedirs { CONFIG_DIR .. "/windows/zlib" }
    filter {}
